    [Fact]
    public async Task ResetAsync_FileMissingFromDisk_ReportsFailure()
    {
        // If the resetter intends to delete a file but it does not exist
        // on disk, the returned Failed list includes it — we must not
        // silently claim "reset-removed" for files we never actually deleted.
        using var repo = TestRepository.Create();
        await InitRepoWithTrackedFile(repo.Root, "src/foo.cs", "content");
        await WritePreRunSnapshot(repo.Root, "test-task"); // empty snapshot

        // Use a custom invoker that reports a phantom file in ls-files.
        var sim = new GitSimEngine();
        var phantom = "phantom-missing-file.log";
        var lyingInvoker = new PhantomFileGitInvoker(sim, phantom);

        var result = await WorktreeResetter.ResetAsync(
            repo.Root, "test-task", tasksDir: null, CancellationToken.None, lyingInvoker);

        Assert.False(result.SnapshotMissing);

        // The phantom was in the intent list but wasn't on disk,
        // so it must appear in Failed, not Removed.
        Assert.Contains(phantom, result.Failed);
        Assert.DoesNotContain(phantom, result.Removed);
    }

    private sealed class PhantomFileGitInvoker(GitSimEngine inner, string phantomPath) : IGitInvoker
    {
        public async Task<(int ExitCode, string Output, bool TimedOut)> RunAsync(
            string rootPath,
            IEnumerable<string> arguments,
            CancellationToken cancellationToken,
            TimeSpan? timeout = null,
            IReadOnlyDictionary<string, string>? environment = null,
            CancellationToken killToken = default,
            Action<string>? onActivity = null)
        {
            var args = arguments as IReadOnlyList<string> ?? arguments.ToList();

            if (args is ["-c", "core.quotePath=false", "ls-files", "--others", "--exclude-standard"])
            {
                var realResult = await inner.RunAsync(rootPath, args, cancellationToken, timeout, environment, killToken, onActivity);
                // Append the phantom path so the resetter tries to delete it.
                return (realResult.ExitCode, realResult.Output + phantomPath + "\n", realResult.TimedOut);
            }

            return await inner.RunAsync(rootPath, args, cancellationToken, timeout, environment, killToken, onActivity);
        }
    }
}

